    private static final Map<String, short[]> TICKS = parse();

    private CrewClipLengths() {}

    /** Lengths for the pool with this prefix, index 0 = clip 1, or null when not generated. */
    public static short[] of(String prefix) {
        return TICKS.get(prefix);
    }

    private static Map<String, short[]> parse() {
        Map<String, short[]> map = new HashMap<>();
        for (String row : String.join("", DATA).split(";")) {
            int colon = row.indexOf(':');
            String[] parts = row.substring(colon + 1).split(",");
            short[] t = new short[parts.length];
            for (int i = 0; i < parts.length; i++) t[i] = Short.parseShort(parts[i]);
            map.put(row.substring(0, colon), t);
        }
        return map;
    }
